def test_daily_bars_most_recent_first_trimmed_and_cached():
    bars = [_bar(d, 100 + d) for d in (3, 1, 2)]
    client, seen = _client([_Resp(200, {"bars": {"BRK.B": bars}})])
    out = client.daily_bars(["BRK-B", "RHM.DE"], 2)
    assert [r["date"] for r in out["BRK-B"]] == ["2026-01-03", "2026-01-02"]
    assert out["BRK-B"][0] == {
        "date": "2026-01-03",
        "open": 102,
        "high": 104,
        "low": 101,
        "close": 103,
        "adjClose": 103,
        "volume": 1_000_000,
    }
    assert "RHM.DE" not in out
    assert seen[0]["symbols"] == "BRK.B" and seen[0]["feed"] == "sip"
    # A smaller window is served from the cache without another request.
    assert len(client.daily_bars(["BRK-B"], 1)["BRK-B"]) == 1
    assert client.calls_made == 1


def test_pagination_and_iex_fallback_on_403():
    client, seen = _client(
        [
            _Resp(403, text="forbidden"),
            _Resp(200, {"bars": {"AAPL": [_bar(1, 10)]}, "next_page_token": "p2"}),
            _Resp(200, {"bars": {"AAPL": [_bar(2, 11)]}}),
        ]
    )
    out = client.daily_bars(["AAPL"], 5)
    assert [r["close"] for r in out["AAPL"]] == [11, 10]
    assert client.feed == "iex"
    assert [p["feed"] for p in seen] == ["sip", "iex", "iex"]
    assert seen[2]["page_token"] == "p2"


