def test_daily_bars_between_filters_inclusive_range():
    bars = [_bar(d, 100 + d) for d in (1, 2, 3, 4)]
    client, seen = _client([_Resp(200, {"bars": {"AAPL": bars}})])
    rows = client.daily_bars_between("AAPL", "2026-01-02", "2026-01-03")
    assert [r["date"] for r in rows] == ["2026-01-02", "2026-01-03"]
    assert seen[0]["start"] == "2026-01-02" and seen[0]["end"] == "2026-01-04"
    assert client.daily_bars_between("RHM.DE", "2026-01-02", "2026-01-03") is None


