def test_quotes_derived_from_bars():
    bars = [_bar(d, 100 + d, volume=1000 * d) for d in (1, 2, 3)]
    client, _ = _client([_Resp(200, {"bars": {"AAPL": bars}})])
    q = client.quotes(["AAPL"])["AAPL"]
    assert q["price"] == 103 and q["previousClose"] == 102
    assert q["change"] == 1 and q["changesPercentage"] == pytest.approx(100 / 102)
    assert q["yearHigh"] == 104 and q["yearLow"] == 99
    assert q["avgVolume"] == 2000 and q["priceAvg50"] == 102
    assert q["dataSource"] == "alpaca" and "marketCap" not in q
